import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.Cd7mb1YL.js";const w=JSON.parse('{"title":"MawyHtmlPolicy","description":"What becomes of raw HTML written inside a document.","frontmatter":{"title":"MawyHtmlPolicy","order":9},"headers":[],"relativePath":"api/types/html-policy.md","filePath":"en/api/types/html-policy.md","lastUpdated":1789099024000}'),n={name:"api/types/html-policy.md"};function o(h,e,c,l,r,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="mawyhtmlpolicy" tabindex="-1"><code>MawyHtmlPolicy</code> <a class="header-anchor" href="#mawyhtmlpolicy" aria-label="Permalink to &quot;`MawyHtmlPolicy`&quot;">​</a></h1><p>What becomes of raw HTML written inside a document.</p><div class="mawy-fw" data-fw="flutter"><p>This one is the React package&#39;s. Raw HTML in a document is shown here as the characters it was written with, and there is no option to change that, because Flutter has no HTML to draw it as. It is the one place the two packages differ about a document, and the difference is in what the screen can do rather than in what the document says.</p></div><div class="mawy-fw" data-fw="react"><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MawyHtmlPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;escape&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sanitize&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;raw&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li><code>&#39;escape&#39;</code> — it is shown as the characters it was written with. The default, and the only one that is safe without qualification.</li><li><code>&#39;sanitize&#39;</code> — it is drawn, with everything outside an allowlist of elements, attributes and URL schemes removed first.</li><li><code>&#39;raw&#39;</code> — it is drawn as written. Nothing is removed and nothing is checked: a <code>&lt;script&gt;</code> in the document runs, an <code>onerror</code> on an image runs, and an <code>&lt;iframe&gt;</code> loads — in the page&#39;s own origin, with the page&#39;s own cookies. <strong>Anybody who can put characters into the document can do anything the application can do.</strong> Set it for documents the application wrote or has already made safe itself.</li></ul><p>None of the three affects links. <code>[click](javascript:…)</code> is refused under every policy, because it is Markdown rather than HTML and switching the HTML policy was never a statement about it. See <a href="./../../guide/viewer#safety">safety</a>.</p></div>',4)])])}const y=t(n,[["render",o]]);export{w as __pageData,y as default};
